/*common.coco.updateAppPath_defaultApproval*/
	UPDATE ICOMAPPT
	SET DEFAULT_FLAG = 'N'
	WHERE 1=1
	AND USER_ID = #{st_user_id}


/*common.coco.deleteAppPathRemove_appt*/
	UPDATE ICOMAPPT
	SET STATUS = 'D',
	    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
	    CHANGE_USER_ID = #{st_user_id}
	WHERE 1=1
	    AND USER_ID = #{st_user_id}
	    AND APP_PATH = #{app_path}


/*common.coco.deleteAppPathRemove_apse*/
	UPDATE ICOMAPSE
	SET STATUS = 'D',
	    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
	    CHANGE_USER_ID = #{st_user_id}
	WHERE 1=1
	    AND USER_ID = #{st_user_id}
	    AND APP_PATH = #{app_path}

