/*common.coco.getApprovalMultiPathUserNm_arry*/
SELECT ROWNUM, T.GUBUN, T.USER_ID, T.USER_NAME_LOC, T.DEPARTMENT, T.POSITION FROM (
SELECT DECODE(#{gubun}, '결재', DECODE(SUBSTR(#{user_id}, 0, 1), '^', '합의', #{gubun}), #{gubun}) AS GUBUN, USER_ID, USER_NAME_LOC , ( SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = COM_CODE AND TYPE='C001' AND CODE = DEPARTMENT ) AS DEPARTMENT, ( SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = COM_CODE AND TYPE='C003' AND CODE = POSITION ) AS POSITION FROM ICOMLUSR WHERE (STATUS='C' OR STATUS='R') AND USER_ID IN (REPLACE(#{user_id}, '^', ''))
) T

